success.command:
cat > src/styles.css <<'EOF'
:root {
  --bg: #f5f6f8;
  --surface: #ffffff;
  --border: #e3e6ec;
  --text: #171a21;
  --muted: #6b7280;
  --accent: #4f46e5;
  --green: #16a34a;
  --green-bg: #22c55e;
  --green-soft: #dcfce7;
  --sleep-bg: #eef0f4;
  --sleep-text: #aab0bd;
  --awake-bg: #ffffff;
  --warn-bg: #fff4e5;
  --warn-text: #9a5b00;
  --radius: 12px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1116;
    --surface: #171a22;
    --border: #2a2f3b;
    --text: #eceef3;
    --muted: #8b93a3;
    --accent: #818cf8;
    --green: #4ade80;
    --green-bg: #16a34a;
    --green-soft: #12351f;
    --sleep-bg: #12141a;
    --sleep-text: #4b5262;
    --awake-bg: #232836;
    --warn-bg: #3a2a10;
    --warn-text: #fbbf24;
    color-scheme: dark;
  }
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.45 -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", Roboto, sans-serif;
  -webkit-font-asmoothing: antialiased;
}
button, select, input { font: inherit; color: inherit; }
.app { max-width: 1120px; margin: 0 auto; padding: 32px 20px 48px; display: flex; flex-direction: column; gap: 16px; }
.header { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; }
.title { margin: 0; font-size: 28px; letter-spacing: -0.02em; }
.subtitle { margin: 2px 0 0; color: var(--muted); }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; box-shadow: 0 1px 2px rgb(0 0 0 / 0.04); }
.card-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }
.section-title { margin: 0; font-size: 16px; }
.muted { color: var(--muted); }
.small { font-size: 12px; }

.segmented { display: inline-flex; background: var(--sleep-bg); border: 1px solid var(--border); border-radius: 10px; padding: 3px; gap: 2px; }
.seg { border: 0; background: transparent; padding: 7px 16px; border-radius: 8px; cursor: pointer; color: var(--muted); font-weight: 500; }
.small .seg, .segmented.small .seg { padding: 5px 12px; }
.seg.active { background: var(--surface); color: var(--text); box-shadow: 0 1px 3px rgb(0 0 0 / 0.15); }

.settings { display: flex; gap: 24px; flex-wrap: wrap; align-items: flex-end; padding: 16px 20px; }
.field { display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: var(--muted); font-weight: 500; }
.field select { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 7px 10px; min-width: 110px; font-size: 14px; color: var(--text); }

.btn { border: 1px solid var(--border); background: var(--surface); padding: 8px 14px; border-radius: 9px; cursor: pointer; font-weight: 500; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn:focus-visible, .seg:focus-visible, .city-name:focus-visible, .icon-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.picker { position: relative; }
.popover { position: absolute; right: 0; top: calc(100% + 6px); width: 300px; z-index: 20; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; box-shadow: 0 12px 32px rgb(0 0 0 / 0.2); padding: 8px; }
.search { width: 100%; padding: 8px 10px; border-radius: 8px; border: 1px solid var(--border); background: var(--bg); outline: none; }
.search:focus { border-color: var(--accent); }
.options { list-style: none; margin: 6px 0 0; padding: 0; max-height: 260px; overflow-y: auto; }
.option { display: flex; justify-content: space-between; gap: 8px; padding: 8px 10px; border-radius: 7px; cursor: pointer; font-size: 14px; }
.option.active { background: var(--sleep-bg); }
.option .muted { font-size: 12px; }
.no-results { padding: 10px; color: var(--muted); font-size: 14px; }

.summary { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; padding: 12px 14px; background: var(--green-soft); border-radius: 10px; }
.summary:has(> .warn) { background: var(--warn-bg); }
.summary-line { display: flex; flex-wrap: wrap; gap: 8px 10px; align-items: center; }
.ranges { display: inline-flex; flex-wrap: wrap; gap: 6px; }
.badge { background: var(--surface); border: 1px solid var(--green); color: var(--green); border-radius: 999px; padding: 1px 10px; font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; }
.warn { margin: 0; color: var(--warn-text); font-weight: 500; }
.warn.inline { font-size: 14px; }

.cell { display: flex; align-items: center; justify-content: center; height: 40px; border-radius: 6px; font-size: 12px; font-variant-numeric: tabular-nums; border: 1px solid var(--border); background: var(--awake-bg); overflow: hidden; white-space: nowrap; }
.cell.sleep { background: var(--sleep-bg); color: var(--sleep-text); border-color: transparent; opacity: 0.75; }
.cell.overlap { background: var(--green-bg); color: #fff; font-weight: 700; border-color: var(--green-bg); }

.dgrid { display: flex; flex-direction: column; gap: 6px; }
.drow { display: grid; grid-template-columns: 190px minmax(0, 1fr) 32px; gap: 12px; align-items: center; }
.d-info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.d-cells { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); gap: 3px; }
.d-action { display: flex; justify-content: center; }
.hour-head { text-align: center; font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }
.drow.head { margin-bottom: 2px; }

.city-name-wrap { display: inline-flex; align-items: center; gap: 6px; }
.city-name { border: 0; background: none; padding: 0; font-weight: 600; font-size: 15px; cursor: pointer; text-align: left; }
.city-name:hover:not(:disabled) { color: var(--accent); text-decoration: underline; }
.city-name:disabled { cursor: default; }
.ref-badge { font-size: 10px; font-weight: 700; letter-spacing: 0.06em; padding: 1px 6px; border-radius: 5px; background: var(--accent); color: #fff; }
.icon-btn { width: 28px; height: 28px; border-radius: 8px; border: 0; background: transparent; color: var(--muted); font-size: 20px; line-height: 1; cursor: pointer; }
.icon-btn:hover { background: var(--sleep-bg); color: #dc2626; }

.mscroll { overflow-x: auto; margin: 0 -8px; padding: 0 8px; }
.mgrid { display: grid; gap: 3px; align-items: stretch; }
.m-head { display: flex; flex-direction: column; align-items: center; gap: 2px; text-align: center; padding-bottom: 6px; }
.m-head .city-name-wrap { flex-wrap: wrap; justify-content: center; }
.m-head .city-name { font-size: 13px; text-align: center; }
.tiny-text { font-size: 11px; }
.icon-btn.tiny { width: 22px; height: 22px; font-size: 16px; }
.m-hour { display: flex; align-items: center; justify-content: flex-start; font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; position: sticky; left: 0; background: var(--surface); }
.mgrid .cell { height: 34px; }

.hint { margin: 16px 0 0; color: var(--muted); font-size: 13px; display: flex; align-items: center; gap: 8px; }
.swatch { width: 12px; height: 12px; border-radius: 3px; background: var(--green-bg); display: inline-block; }
.empty { color: var(--muted); text-align: center; padding: 24px 0; }

@media (max-width: 767px) {
  .app { padding: 20px 12px 32px; }
  .card { padding: 14px; }
  .title { font-size: 24px; }
  .popover { width: min(300px, calc(100vw - 48px)); }
}
EOF
pnpm typecheck 2>&1 | tail -20; pnpm build 2>&1 | tail -5

